"use client";

import { AlertTriangle, Info } from "lucide-react";
import { cn } from "@/lib/utils";

interface DemoBannerProps {
  message?: string;
  type?: "info" | "warning";
  className?: string;
}

export function DemoBanner({
  message,
  type = "warning",
  className,
}: DemoBannerProps) {
  const defaultMessages = {
    warning:
      "⚠️ Demo Mode — The results shown below are simulated sample data and are not generated by a real AI service. No actual analysis of your resume or the job description has been performed.",
    info:
      "ℹ️ This page contains demo content for illustration purposes. No real data is being saved or processed.",
  };

  return (
    <div
      role="alert"
      className={cn(
        "flex gap-3 rounded-lg border px-4 py-3 text-sm",
        type === "warning"
          ? "bg-amber-50 border-amber-200 text-amber-800"
          : "bg-blue-50 border-blue-200 text-blue-800",
        className
      )}
    >
      {type === "warning" ? (
        <AlertTriangle className="w-4 h-4 mt-0.5 shrink-0" />
      ) : (
        <Info className="w-4 h-4 mt-0.5 shrink-0" />
      )}
      <p>{message ?? defaultMessages[type]}</p>
    </div>
  );
}
